insert into public.properties (id, kind, status, sort_order, data) values ('h1', 'hotel', 'published', 10, $ds${"id":"h1","category":"budget","name":{"en":"Cataract Layalina","ar":"كاتاراكت ليالينا","ru":"Cataract Layalina","de":"Cataract Layalina","it":"Cataract Layalina","tr":"Cataract Layalina"},"description":{"en":"4-star hotel with sea view","ar":"فندق 4 نجوم بإطلالة على البحر","ru":"Роскошный 5-звездочный отель с видом на море","de":"Luxus-5-Sterne-Hotel mit Meerblick","it":"Hotel di lusso 5 stelle con vista mare","tr":"Deniz manzaralı lüks 5 yıldızlı otel"},"fullDescription":{"en":"Experience unparalleled luxury at Discover Grand Hotel. Featuring stunning Red Sea views, world-class amenities, and exceptional service that defines the essence of Sharm El Sheikh hospitality.","ar":"استمتع بتجربة فخامة لا مثيل لها في فندق ديسكفر جراند، بإطلالات ساحرة على البحر الأحمر ومرافق عالمية المستوى وخدمة استثنائية تجسد روح الضيافة في شرم الشيخ.","ru":"Ощутите непревзойденную роскошь в Discover Grand Hotel — потрясающий вид на Красное море, первоклассные удобства и безупречный сервис, отражающий дух гостеприимства Шарм-эль-Шейха.","de":"Erleben Sie unvergleichlichen Luxus im Discover Grand Hotel mit atemberaubendem Blick auf das Rote Meer, erstklassigen Annehmlichkeiten und außergewöhnlichem Service.","it":"Vivi un lusso senza pari al Discover Grand Hotel, con splendide vedute sul Mar Rosso, servizi di livello mondiale e un'ospitalità eccezionale, tipica di Sharm El Sheikh.","tr":"Discover Grand Hotel'de eşsiz bir lüks deneyimi yaşayın — büyüleyici Kızıldeniz manzarası, dünya standartlarında olanaklar ve Sharm El Sheikh misafirperverliğini yansıtan üstün hizmet."},"price":3800,"rating":5,"reviews":234,"location":{"en":"123 Naama Bay, Sharm El Sheikh","ar":"١٢٣ خليج نعمة، شرم الشيخ","ru":"Naama Bay 123, Шарм-эль-Шейх","de":"Naama Bay 123, Sharm El Sheikh","it":"Naama Bay 123, Sharm El Sheikh","tr":"Naama Bay 123, Sharm El Sheikh"},"image":"https://www.hotelsharmelsheikhegypt.com/data/Pics/OriginalPhoto/10769/1076965/1076965390/pic-cataract-resort-aqua-park-naama-bay-sharm-el-sheikh-42.JPEG","images":["https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=800&q=90","https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=90","https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=800&q=90"],"amenities":{"en":["Free WiFi","Breakfast","Pool","Spa","Gym","Parking"],"ar":["واي فاي مجاني","إفطار","مسبح","سبا","صالة رياضية","موقف سيارات"],"ru":["Бесплатный Wi-Fi","Завтрак","Бассейн","Спа","Тренажерный зал","Парковка"],"de":["Kostenloses WLAN","Frühstück","Pool","Spa","Fitnessstudio","Parkplatz"],"it":["WiFi gratuito","Colazione","Piscina","Spa","Palestra","Parcheggio"],"tr":["Ücretsiz WiFi","Kahvaltı","Havuz","Spa","Spor Salonu","Otopark"]},"bestseller":true,"rooms":[{"type":{"en":"Deluxe Sea View","ar":"ديلوكس بإطلالة على البحر","ru":"Делюкс с видом на море","de":"Deluxe Meerblick","it":"Deluxe Vista Mare","tr":"Deniz Manzaralı Delüks"},"price":3800,"size":"35m²","beds":{"en":"1 King Bed","ar":"سرير كينج واحد","ru":"1 кровать king-size","de":"1 Kingsize-Bett","it":"1 letto king","tr":"1 King Yatak"},"guests":2,"image":"https://images.unsplash.com/photo-1631049307264-da0ec9d70304?auto=format&fit=crop&w=400&q=80","description":{"en":"A bright, airy room with floor-to-ceiling windows framing the Red Sea. Soft linens, a marble bathroom, and a private balcony make this the hotel's signature room.","ar":"غرفة مشرقة وواسعة بنوافذ ممتدة من الأرض إلى السقف تطل على البحر الأحمر، مع مفروشات ناعمة وحمام رخامي وشرفة خاصة.","ru":"Светлый просторный номер с панорамными окнами и видом на Красное море, мраморной ванной комнатой и собственным балконом.","de":"Ein helles, luftiges Zimmer mit bodentiefen Fenstern zum Roten Meer, weicher Bettwäsche, Marmorbad und privatem Balkon.","it":"Camera luminosa con finestre a tutta altezza sul Mar Rosso, biancheria morbida, bagno in marmo e balcone privato.","tr":"Kızıldeniz manzaralı yerden tavana pencereleri, yumuşak nevresimleri, mermer banyosu ve özel balkonuyla otelin amiral gemisi odası."},"baseOccupancy":2,"extraAdultFee":950,"freeChildrenPerRoom":2,"extraChildFee":480},{"type":{"en":"Premium Suite","ar":"جناح بريميوم","ru":"Премиум люкс","de":"Premium-Suite","it":"Suite Premium","tr":"Premium Suit"},"price":6900,"size":"65m²","beds":{"en":"1 King Bed","ar":"سرير كينج واحد","ru":"1 кровать king-size","de":"1 Kingsize-Bett","it":"1 letto king","tr":"1 King Yatak"},"guests":3,"image":"https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=400&q=80","description":{"en":"A spacious two-area suite with a separate lounge, walk-in closet, and panoramic sea-facing terrace — ideal for longer stays.","ar":"جناح فسيح بمنطقتين مع صالة منفصلة وخزانة ملابس وتراس بانورامي مطل على البحر — مثالي للإقامات الطويلة.","ru":"Просторный люкс из двух зон с отдельной гостиной, гардеробной и панорамной террасой с видом на море.","de":"Eine geräumige Zwei-Zonen-Suite mit separater Lounge, begehbarem Kleiderschrank und Panoramaterrasse zum Meer.","it":"Ampia suite a due zone con salotto separato, cabina armadio e terrazza panoramica sul mare.","tr":"Ayrı oturma alanı, giyinme odası ve denize bakan panoramik teraslı geniş iki bölümlü suit."},"baseOccupancy":2,"extraAdultFee":1720,"freeChildrenPerRoom":2,"extraChildFee":860}],"unavailableDates":["2026-09-05","2026-09-06","2026-09-07","2026-09-23","2026-10-08"]}$ds$::jsonb)
  on conflict (id) do update set data = excluded.data, sort_order = excluded.sort_order;
insert into public.properties (id, kind, status, sort_order, data) values ('h2', 'hotel', 'published', 20, $ds${"id":"h2","category":"luxury","name":{"en":"Cataract Resort Aqua Park","ar":"منتجع كاتاراكت - أكوابارك","ru":"Cataract Resort Aqua Park","de":"Cataract Resort Aqua Park","it":"Cataract Resort Aqua Park","tr":"Cataract Resort Aqua Park"},"description":{"en":"Elegant suites with panoramic views","ar":"أجنحة أنيقة بإطلالات بانورامية","ru":"Элегантные люксы с панорамным видом","de":"Elegante Suiten mit Panoramablick","it":"Eleganti suite con vista panoramica","tr":"Panoramik manzaralı zarif suitler"},"fullDescription":{"en":"Discover Deluxe Suites offers an intimate luxury experience with spacious suites, private balconies overlooking the Red Sea, and personalized service for the discerning traveler.","ar":"يقدم ديسكفر ديلوكس سويتس تجربة فخامة حميمية بأجنحة واسعة وشرفات خاصة تطل على البحر الأحمر وخدمة شخصية للمسافر المميز.","ru":"Discover Deluxe Suites предлагает изысканный отдых в просторных люксах с личными балконами с видом на Красное море.","de":"Discover Deluxe Suites bietet ein intimes Luxuserlebnis mit geräumigen Suiten und privaten Balkonen zum Roten Meer.","it":"Discover Deluxe Suites offre un'esperienza di lusso intima con ampie suite e balconi privati affacciati sul Mar Rosso.","tr":"Discover Deluxe Suites, geniş suitleri ve Kızıldeniz'e bakan özel balkonlarıyla samimi bir lüks deneyimi sunar."},"price":4750,"rating":5,"reviews":189,"location":{"en":"456 Sharks Bay, Sharm El Sheikh","ar":"٤٥٦ خليج القرش، شرم الشيخ","ru":"Sharks Bay 456, Шарм-эль-Шейх","de":"Sharks Bay 456, Sharm El Sheikh","it":"Sharks Bay 456, Sharm El Sheikh","tr":"Sharks Bay 456, Sharm El Sheikh"},"image":"https://www.hotelsharmelsheikhegypt.com/data/Pics/OriginalPhoto/10769/1076965/1076965390/pic-cataract-resort-aqua-park-naama-bay-sharm-el-sheikh-42.JPEG","images":["https://www.hotelsharmelsheikhegypt.com/data/Pics/OriginalPhoto/10769/1076965/1076965390/pic-cataract-resort-aqua-park-naama-bay-sharm-el-sheikh-42.JPEG","https://cf.bstatic.com/xdata/images/hotel/max1024x768/716939830.jpg?k=430ad9d374253dee495aeaa8203d1952dea38915dc9b601f477f023b5eb79bdf&o=","https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSv3Pm7KJNt8Wpq6SVfZjEQEThtRTJvaBtD5M8qlDL0gLQFHYeY6PWoo6A&s=10","https://q-xx.bstatic.com/xdata/images/hotel/max500/712720873.jpg?k=df9b173165fb80065bba9ad8934216d49e212679a5db7acf3afd68a2dc72a87a&o=","https://q-xx.bstatic.com/xdata/images/hotel/max500/716940913.jpg?k=b53afcad40447bf4b370c586313ff5defed59dcb20f975d3406e5b623aba88f0&o="],"amenities":{"en":["Free WiFi","Breakfast","Gym","Beach Access","Concierge"],"ar":["واي فاي مجاني","إفطار","صالة رياضية","وصول مباشر للشاطئ","خدمة كونسيرج"],"ru":["Бесплатный Wi-Fi","Завтрак","Тренажерный зал","Выход на пляж","Консьерж"],"de":["Kostenloses WLAN","Frühstück","Fitnessstudio","Strandzugang","Concierge"],"it":["WiFi gratuito","Colazione","Palestra","Accesso alla spiaggia","Concierge"],"tr":["Ücretsiz WiFi","Kahvaltı","Spor Salonu","Plaj Erişimi","Concierge"]},"bestseller":true,"rooms":[{"type":{"en":"Junior Suite","ar":"جناح جونيور","ru":"Джуниор люкс","de":"Junior-Suite","it":"Junior Suite","tr":"Junior Suit"},"price":4750,"size":"45m²","beds":{"en":"1 King Bed","ar":"سرير كينج واحد","ru":"1 кровать king-size","de":"1 Kingsize-Bett","it":"1 letto king","tr":"1 King Yatak"},"guests":2,"image":"https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=400&q=80","description":{"en":"An elegant junior suite with a private balcony, sitting area, and rain shower — quiet, comfortable and close to the beach path.","ar":"جناح جونيور أنيق بشرفة خاصة ومنطقة جلوس ودُش مطري — هادئ ومريح وقريب من ممر الشاطئ.","ru":"Элегантный джуниор-люкс с личным балконом, зоной отдыха и тропическим душем.","de":"Eine elegante Junior-Suite mit privatem Balkon, Sitzbereich und Regendusche.","it":"Un'elegante junior suite con balcone privato, area salotto e doccia a pioggia.","tr":"Özel balkonu, oturma alanı ve yağmurlama duşuyla şık bir junior suit."},"baseOccupancy":2,"extraAdultFee":1190,"freeChildrenPerRoom":2,"extraChildFee":600}],"unavailableDates":["2026-08-29","2026-08-30","2026-09-13","2026-09-14","2026-09-15"]}$ds$::jsonb)
  on conflict (id) do update set data = excluded.data, sort_order = excluded.sort_order;
insert into public.properties (id, kind, status, sort_order, data) values ('e1', 'excursion', 'published', 10, $ds${"id":"e1","category":"Boat trip","title":{"ar":"رحلة سنوركل رأس محمد","en":"Ras Mohammed Snorkeling Trip","ru":"Снорклинг-тур в Рас-Мохаммед","de":"Ras-Mohammed-Schnorcheltour","it":"Escursione Snorkeling a Ras Mohammed","tr":"Ras Muhammed Şnorkel Turu"},"price":1700,"rating":4.8,"reviews":268,"duration":{"ar":"يوم كامل (٨ ساعات)","en":"Full Day (8h)","ru":"Целый день (8 ч)","de":"Ganzer Tag (8 Std.)","it":"Giornata intera (8h)","tr":"Tam Gün (8s)"},"image":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR198euI0KuyPgFLPb62ocPQNohqGHLSbCezSgbAY6Cc4WZUHLTTp4snMo&s=10","images":["https://media-cdn.tripadvisor.com/media/attractions-splice-spp-674x446/10/46/40/61.jpg","https://egyptra.pro/img.php?src=uploads%2Fproducts%2Fimg_cfdc48ab0be8b871.webp&w=740&h=555&crop=1&q=72","https://dynamic-media.tacdn.com/media/photo-o/2f/38/6e/8d/caption.jpg?w=1100&h=800&s=1","https://dynamic-media.tacdn.com/media/photo-o/2f/38/fb/05/caption.jpg?w=1100&h=800&s=1","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/edb33505f3ccc56849da55242531fcac8530659a06e8af69cd304df5cabf0315.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/67b53f10fd4e35a8d4711d8552c92af300a3aa3d662fc3ec8e20ce68a4f69c38.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/04f0b5a446deb2c2e4ac7c5c301d7cbcae6ab2776b906e2ff20661dcbda4bdb0.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/b8113fd8a4cf5e50fd502452ab70da19cd7d5878a5f9f290574fb1aa6bdbe737.jpg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/e4840fd866aeea27686ccb514774043cf33d1e4883205ad69fd574d5c8c7551a.jpg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/b5925fb301b34f7c7f89f362d85cd721f32edf364247e72ee6c741aea93ccd99.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/ef6f364533457ac4e6ad3abcab002f6c081a29af3bf31ea4d844252868731888.jpeg"],"description":{"ar":"مارس السنوركل بين الشعاب المرجانية في محمية رأس محمد، أحد أفضل مواقع الغوص في العالم.","en":"Snorkel the coral reefs of Ras Mohammed National Park, one of the world's top dive sites.","ru":"Понырять с маской у коралловых рифов национального парка Рас-Мохаммед — одного из лучших дайв-сайтов мира.","de":"Schnorcheln Sie an den Korallenriffen des Ras-Mohammed-Nationalparks, einem der besten Tauchspots der Welt.","it":"Fai snorkeling tra le barriere coralline del Parco Nazionale di Ras Mohammed, uno dei migliori siti di immersione al mondo.","tr":"Dünyanın en iyi dalış noktalarından biri olan Ras Muhammed Milli Parkı'nın mercan resiflerinde şnorkel yapın."},"fullDescription":{"ar":"اقضِ يومًا كاملاً في استكشاف حدائق المرجان وجدران الشعاب المذهلة في محمية رأس محمد. يشمل معدات سنوركل كاملة وإحاطة عن الحياة البحرية وغداء على الشاطئ.","en":"Spend a full day exploring the coral gardens and dramatic reef walls of Ras Mohammed National Park. Includes full snorkeling gear, a marine-life briefing, and a beachside lunch. Suitable for beginners and experienced snorkelers alike.","ru":"Проведите целый день, исследуя коралловые сады и рифовые стены национального парка Рас-Мохаммед. В программе — снаряжение, инструктаж и обед на пляже.","de":"Verbringen Sie einen ganzen Tag mit der Erkundung der Korallengärten und Riffwände des Ras-Mohammed-Nationalparks. Inklusive Ausrüstung, Briefing und Strandmittagessen.","it":"Trascorri un'intera giornata esplorando i giardini di corallo e le pareti della barriera del Parco Nazionale di Ras Mohammed. Include attrezzatura, briefing e pranzo in spiaggia.","tr":"Ras Muhammed Milli Parkı'nın mercan bahçelerini ve resif duvarlarını keşfederek tam bir gün geçirin. Şnorkel ekipmanı, deniz canlıları brifingi ve sahilde öğle yemeği dahildir."},"includes":{"ar":["نقل من وإلى الفندق","معدات سنوركل","غداء ومشروبات غازية","رسوم دخول المحمية","مرشد يتحدث الإنجليزية"],"en":["Hotel pickup & drop-off","Snorkeling equipment","Lunch & soft drinks","National park entry fees","English-speaking guide"],"ru":["Трансфер от/до отеля","Снаряжение для снорклинга","Обед и напитки","Входные билеты в парк","Англоговорящий гид"],"de":["Hotelabholung & Rückfahrt","Schnorchelausrüstung","Mittagessen & Softdrinks","Eintritt Nationalpark","Englischsprachiger Guide"],"it":["Transfer da/per l'hotel","Attrezzatura da snorkeling","Pranzo e bibite","Biglietto d'ingresso al parco","Guida in inglese"],"tr":["Otelden alış-bırakış","Şnorkel ekipmanı","Öğle yemeği ve içecekler","Milli park giriş ücreti","İngilizce konuşan rehber"]},"meetingPoint":{"ar":"الاستلام من لوبي الفندق، ٧:٣٠ صباحًا","en":"Hotel lobby pickup, 7:30 AM","ru":"Встреча в лобби отеля, 7:30","de":"Abholung Hotellobby, 7:30 Uhr","it":"Ritiro in hotel, ore 7:30","tr":"Otel lobisinden alış, 07:30"},"excludes":{"ar":["المشروبات الكحولية","استئجار كاميرا تحت الماء","الإكراميات (اختياري)"],"en":["Alcoholic beverages","Underwater camera rental","Gratuities (optional)"],"ru":["Алкогольные напитки","Аренда подводной камеры","Чаевые (по желанию)"],"de":["Alkoholische Getränke","Unterwasserkamera-Verleih","Trinkgelder (optional)"],"it":["Bevande alcoliche","Noleggio fotocamera subacquea","Mance (facoltative)"],"tr":["Alkollü içecekler","Sualtı kamerası kiralama","Bahşiş (isteğe bağlı)"]},"whatToBring":{"ar":["ملابس سباحة","منشفة","واقي شمس","صندل مريح"],"en":["Swimsuit","Towel","Sunscreen","Comfortable sandals"],"ru":["Купальник","Полотенце","Солнцезащитный крем","Удобные сандалии"],"de":["Badeanzug","Handtuch","Sonnencreme","Bequeme Sandalen"],"it":["Costume da bagno","Asciugamano","Crema solare","Sandali comodi"],"tr":["Mayo","Havlu","Güneş kremi","Rahat sandalet"]},"itinerary":[{"time":"07:30","title":{"ar":"الاستلام من الفندق","en":"Hotel Pickup","ru":"Встреча в отеле","de":"Hotelabholung","it":"Ritiro in hotel","tr":"Otelden Alış"},"description":{"ar":"سيارتنا المكيّفة تستلمك من لوبي الفندق.","en":"Our air-conditioned vehicle collects you from your hotel lobby.","ru":"Наш кондиционируемый автомобиль заберёт вас из лобби отеля.","de":"Unser klimatisiertes Fahrzeug holt Sie von der Hotellobby ab.","it":"Il nostro veicolo climatizzato ti preleva dalla hall dell'hotel.","tr":"Klimalı aracımız sizi otel lobisinden alır."}},{"time":"09:00","title":{"ar":"الوصول والإحاطة","en":"Arrival & Briefing","ru":"Прибытие и инструктаж","de":"Ankunft & Briefing","it":"Arrivo e briefing","tr":"Varış ve Brifing"},"description":{"ar":"قابل مرشدك واحصل على إحاطة قصيرة عن السلامة والحياة البحرية قبل ارتداء المعدات.","en":"Meet your guide and get a short safety and marine-life briefing before gearing up.","ru":"Познакомьтесь с гидом и пройдите короткий инструктаж по безопасности перед экипировкой.","de":"Treffen Sie Ihren Guide und erhalten Sie ein kurzes Sicherheits-Briefing vor der Ausrüstung.","it":"Incontra la tua guida e ricevi un breve briefing sulla sicurezza prima di equipaggiarti.","tr":"Rehberinizle tanışın ve ekipman kuşanmadan önce kısa bir güvenlik brifingi alın."}},{"time":"09:30","title":{"ar":"محطة السنوركل الأولى","en":"First Snorkeling Stop","ru":"Первая остановка для снорклинга","de":"Erster Schnorchelstopp","it":"Prima tappa snorkeling","tr":"İlk Şnorkel Durağı"},"description":{"ar":"استكشف حدائق المرجان في موقع الشعاب الأول.","en":"Explore the coral gardens at the first reef site.","ru":"Исследуйте коралловые сады на первом рифе.","de":"Erkunden Sie die Korallengärten am ersten Riff.","it":"Esplora i giardini di corallo nel primo sito.","tr":"İlk resif noktasındaki mercan bahçelerini keşfedin."}},{"time":"12:00","title":{"ar":"غداء على الشاطئ","en":"Lunch on the Beach","ru":"Обед на пляже","de":"Mittagessen am Strand","it":"Pranzo in spiaggia","tr":"Sahilde Öğle Yemeği"},"description":{"ar":"استراحة غداء هادئة في بقعة شاطئية مظللة داخل المحمية.","en":"A relaxed lunch break at a shaded beach spot inside the park.","ru":"Спокойный обеденный перерыв в тенистом месте на пляже парка.","de":"Eine entspannte Mittagspause an einem schattigen Strandplatz im Park.","it":"Una pausa pranzo rilassante in un punto ombreggiato della spiaggia nel parco.","tr":"Park içinde gölgeli bir sahil noktasında rahat bir öğle yemeği molası."}},{"time":"13:00","title":{"ar":"محطة السنوركل الثانية","en":"Second Snorkeling Stop","ru":"Вторая остановка для снорклинга","de":"Zweiter Schnorchelstopp","it":"Seconda tappa snorkeling","tr":"İkinci Şnorkel Durağı"},"description":{"ar":"موقع شعاب ثانٍ بحياة بحرية مختلفة لاستكشافها.","en":"A second reef site with different marine life to explore.","ru":"Второй риф с иной морской живностью для изучения.","de":"Ein zweites Riff mit anderer Meereswelt zum Erkunden.","it":"Un secondo sito con una fauna marina diversa da esplorare.","tr":"Keşfedilecek farklı deniz canlılarına sahip ikinci bir resif noktası."}},{"time":"15:30","title":{"ar":"العودة إلى الفندق","en":"Return to Hotel","ru":"Возвращение в отель","de":"Rückfahrt zum Hotel","it":"Ritorno in hotel","tr":"Otele Dönüş"},"description":{"ar":"استرخِ في الطريق أثناء عودتك إلى فندقك.","en":"Relax on the drive back as we drop you at your hotel.","ru":"Отдохните по пути назад, пока мы довезём вас до отеля.","de":"Entspannen Sie sich auf der Rückfahrt zu Ihrem Hotel.","it":"Rilassati durante il tragitto di ritorno al tuo hotel.","tr":"Sizi otelinize bırakırken dönüş yolunda rahatlayın."}}],"owner":"BwomDIPc14TitJPZwdYjApde6Vy1"}$ds$::jsonb)
